function levD(a,b){if(Math.abs(a.length-b.length)>2)return 9;const d=[];for(let i=0;i<=a.length;i++){d[i]=[i];}for(let j=1;j<=b.length;j++)d[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)d[i][j]=Math.min(d[i-1][j]+1,d[i][j-1]+1,d[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return d[a.length][b.length];}
function sndx(w){w=w.toLowerCase().replace(/[^a-z]/g,'');if(!w)return'';const c={b:1,f:1,p:1,v:1,c:2,g:2,j:2,k:2,q:2,s:2,x:2,z:2,d:3,t:3,l:4,m:5,n:5,r:6};let o=w[0],last=c[w[0]]||0;for(const ch of w.slice(1)){const k=c[ch]||0;if(k&&k!==last)o+=k;last=k;}return(o+'000').slice(0,4);}
function cleanSpeech(txt){const raw=String(txt||'').replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/\s+/g,' ').trim();let s=' '+raw.toLowerCase()+' ';s=s.replace(SPEECH_FILL,' ');
  const names0=[...AIB.L.map(B=>B.name.replace('🤖 ','')),...CAMPERS.L.map(c=>c.name),...AI_NAMES.map(n=>n.replace('🤖 ',''))].map(n=>String(n).toLowerCase().split(' ')[0]).filter(Boolean);const keepN=[];
  names0.forEach(n=>{s=s.replace(new RegExp('\\b'+n+'\\b','g'),()=>{keepN.push(n);return ' qqn'+(keepN.length-1)+'qq ';});});
  SPEECH_FIX.forEach(([r,v])=>{s=s.replace(r,v);});s=s.replace(/ ?qqn(\d+)qq ?/g,(m,i)=>' '+keepN[+i]+' ');
  const names=[...AIB.L.map(B=>B.name.replace('🤖 ','')),...CAMPERS.L.map(c=>c.name),...AI_NAMES.map(n=>n.replace('🤖 ',''))].map(n=>String(n).toLowerCase().split(' ')[0]).filter((v,i,a)=>v&&a.indexOf(v)===i);
  const w=s.trim().split(' ').filter(Boolean),out=[];
  for(let i=0;i<w.length;i++){const tok=w[i],a=tok.replace(/[^a-z']/g,'');let fixed=null;
    if(a&&a.indexOf("'")<0&&!SPEECH_KEEP.has(a)&&!SPEECH_WORDS.includes(a)){
      // a pilot's / camper's name (Gizmo heard as "is mo", "jizmo", "gizmos"…)
      const nx=w[i+1]?w[i+1].replace(/[^a-z]/g,''):'';
      for(const n of names){if(a===n){fixed=n;break;}if(a.length>=3&&(levD(a,n)<=(n.length>=5?2:1)||(sndx(a)===sndx(n)&&Math.abs(a.length-n.length)<=1))){fixed=n;break;}
        if(nx&&!SPEECH_KEEP.has(nx)&&(a+nx).length>=4&&levD(a+nx,n)<=1){fixed=n;i++;break;}}
      if(!fixed&&a.length>=4){let bd=9;for(const k of SPEECH_WORDS){if(Math.abs(k.length-a.length)>1)continue;const d=levD(a,k);if(d<bd&&d<=(k.length>=7?2:1)){bd=d;fixed=k;}}}
      if(!fixed&&a.length>=4){for(const k of SPEECH_WORDS){if(k.length>=4&&sndx(k)===sndx(a)&&Math.abs(k.length-a.length)<=1&&k[0]===a[0]){fixed=k;break;}}}}
    out.push(fixed?tok.replace(/[a-z']+/,fixed):tok);}
  let r=out.join(' ').replace(/\s+/g,' ').trim();names.forEach(n=>{r=r.replace(new RegExp('\\b'+n+'\\b','g'),n[0].toUpperCase()+n.slice(1));});r=r.replace(/^./,c=>c.toUpperCase()).replace(/\bi\b/g,'I');
  const norm=x=>x.toLowerCase().replace(/[^a-z0-9 ]/g,'').replace(/\s+/g,' ').trim();return{text:r,changed:norm(r)!==norm(raw)};}
// every chat line is decoded first (pilots, campers and the AI all read the clean version)
